def git_rev_parse_head(repo_path: Path) -> str:
    r = subprocess.run(
        ["git", "-C", str(repo_path), "rev-parse", "HEAD"],
        capture_output=True,
        text=True,
    )
    if r.returncode != 0:
        fatal_invariant(f"git rev-parse HEAD failed: {r.stderr}")
    return r.stdout.strip()


